-- Generated by Wallust
vim.cmd("highlight clear")
if vim.fn.exists("syntax_on") == 1 then vim.cmd("syntax reset") end
vim.o.termguicolors = true
vim.o.background = "dark"
vim.g.colors_name = "wallust"

-- set to true to let the terminal background (blur/opacity) show through
local transparent = false

local c = {
  bg      = "#1B0F0F",
  bg_alt  = "#220D0C",
  bg_sel  = "#433130",
  fg      = "#FFA5BB",
  fg_dim  = "#EB93AA",
  muted   = "#A85B70",
  red     = "#5C4234",
  green   = "#8A6B5D",
  yellow  = "#8B0846",
  blue    = "#9B2252",
  magenta = "#765950",
  cyan    = "#AE6075",
}

local bg = transparent and "NONE" or c.bg

local groups = {
  -- UI
  Normal       = { fg = c.fg, bg = bg },
  NormalNC     = { fg = c.fg, bg = bg },
  NormalFloat  = { fg = c.fg, bg = c.bg_alt },
  FloatBorder  = { fg = c.blue, bg = c.bg_alt },
  FloatTitle   = { fg = c.blue, bg = c.bg_alt, bold = true },
  CursorLine   = { bg = c.bg_alt },
  CursorLineNr = { fg = c.blue, bold = true },
  LineNr       = { fg = c.muted },
  SignColumn   = { fg = c.muted, bg = bg },
  ColorColumn  = { bg = c.bg_alt },
  Visual       = { bg = c.bg_sel },
  Search       = { fg = c.bg, bg = c.yellow },
  IncSearch    = { fg = c.bg, bg = c.magenta },
  CurSearch    = { fg = c.bg, bg = c.magenta },
  MatchParen   = { fg = c.yellow, bold = true },
  Pmenu        = { fg = c.fg, bg = c.bg_alt },
  PmenuSel     = { fg = c.bg, bg = c.blue },
  PmenuSbar    = { bg = c.bg_alt },
  PmenuThumb   = { bg = c.muted },
  StatusLine   = { fg = c.fg, bg = c.bg_alt },
  StatusLineNC = { fg = c.muted, bg = c.bg_alt },
  WinSeparator = { fg = c.bg_sel },
  TabLine      = { fg = c.muted, bg = c.bg_alt },
  TabLineSel   = { fg = c.fg, bg = c.bg },
  TabLineFill  = { bg = c.bg_alt },
  Folded       = { fg = c.muted, bg = c.bg_alt },
  NonText      = { fg = c.bg_sel },
  Whitespace   = { fg = c.bg_sel },
  EndOfBuffer  = { fg = c.bg },
  Directory    = { fg = c.blue },
  Title        = { fg = c.blue, bold = true },
  ErrorMsg     = { fg = c.red },
  WarningMsg   = { fg = c.yellow },
  Question     = { fg = c.green },

  -- Syntax
  Comment      = { fg = c.muted, italic = true },
  Constant     = { fg = c.cyan },
  String       = { fg = c.green },
  Number       = { fg = c.yellow },
  Boolean      = { fg = c.yellow },
  Identifier   = { fg = c.fg },
  Function     = { fg = c.blue },
  Statement    = { fg = c.magenta },
  Operator     = { fg = c.fg_dim },
  Keyword      = { fg = c.magenta },
  PreProc      = { fg = c.cyan },
  Type         = { fg = c.yellow },
  Special      = { fg = c.cyan },
  Delimiter    = { fg = c.fg_dim },
  Error        = { fg = c.red },
  Todo         = { fg = c.bg, bg = c.yellow, bold = true },
  ["@variable"]           = { fg = c.fg },
  ["@variable.parameter"] = { fg = c.fg_dim, italic = true },
  ["@property"]           = { fg = c.cyan },

  -- Diagnostics
  DiagnosticError = { fg = c.red },
  DiagnosticWarn  = { fg = c.yellow },
  DiagnosticInfo  = { fg = c.blue },
  DiagnosticHint  = { fg = c.cyan },
  DiagnosticOk    = { fg = c.green },
  DiagnosticUnderlineError = { undercurl = true, sp = c.red },
  DiagnosticUnderlineWarn  = { undercurl = true, sp = c.yellow },
  DiagnosticUnderlineInfo  = { undercurl = true, sp = c.blue },
  DiagnosticUnderlineHint  = { undercurl = true, sp = c.cyan },

  -- Diff / git
  Added   = { fg = c.green },
  Changed = { fg = c.yellow },
  Removed = { fg = c.red },
  DiffAdd    = { bg = c.bg_alt, fg = c.green },
  DiffChange = { bg = c.bg_alt, fg = c.yellow },
  DiffDelete = { bg = c.bg_alt, fg = c.red },
  DiffText   = { bg = c.bg_sel, fg = c.fg },
}

for group, opts in pairs(groups) do
  vim.api.nvim_set_hl(0, group, opts)
end